int dvb_diseqc_send_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *cmd) {
    if (cmd->msg_len > DISEQC_MAX_MSG_LEN)
        return -EINVAL;

    memcpy(fe->diseqc_buffer, cmd->msg, cmd->msg_len);
    return fe->ops.send_diseqc_master_cmd(fe, fe->diseqc_buffer, cmd->msg_len);
}

int dvb_send_diseqc_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *cmd)
{
    if (cmd->msg_len > sizeof(fe->diseqc_msg)) {
        return -EINVAL;
    }

    memcpy(fe->diseqc_msg, cmd->msg, cmd->msg_len);
    return fe->ops.send_diseqc_master_cmd(fe, fe->diseqc_msg, cmd->msg_len);
}

int dvb_diseqc_send_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *cmd) {
    if (cmd->msg_len > DVB_DISEQC_MAX_MSG_LEN)
        return -EINVAL;

    memcpy(fe->diseqc_msg, cmd->msg, cmd->msg_len);
    fe->diseqc_msg_len = cmd->msg_len;

    return dvb_diseqc_send_message(fe);
}

int dvb_frontend_send_diseqc_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *cmd)
{
    if (cmd->msg_len > DVB_DISEQC_MAX_MSG_LEN)
        return -EINVAL;

    memcpy(diseqc_tx_buffer, cmd->msg, cmd->msg_len);
    return fe->ops.send_diseqc_master_cmd(fe, diseqc_tx_buffer, cmd->msg_len);
}

int dvb_frontend_send_diseqc_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *cmd) {
    if (cmd->msg_len > MAX_BUFFER_SIZE) {
        return -EINVAL;
    }

    memcpy(buffer, cmd->msg, cmd->msg_len);
    return fe->ops.send_diseqc_master_cmd(fe, buffer, cmd->msg_len);
